/* =========================================================================
 * Strip accents, then lowercase, folded into one lookup: the codepoint HF
 * produces for a single input codepoint, when that is one codepoint and not
 * the input itself. HF's order is strip, then lowercase (Rust's
 * BertNormalizer, which is what tokenizer.json runs).
 *
 * Three run shapes keep the table small:
 *   K  every codepoint of the run maps to `value`        (U+1EA0-1EB7 -> a)
 *   D  every codepoint maps to itself + `value`           (U+0410-042F -> +0x20)
 *   P  alternating case pairs: first, first+2, ... map to
 *      cp + 1, the codepoints in between are unchanged    (U+0460-0480)
 *
 * Letters with no canonical decomposition are only lowercased: AE -> ae,
 * O-stroke -> o-stroke, D-stroke -> d-stroke, L-stroke -> l-stroke, and
 * dotless i, long s and sharp s are left alone. Vietnamese horn letters
 * (U+01A0, U+01AF) do decompose, so they fold to o / u.
 * ========================================================================= */
enum class FoldShape : char { K = 'K', D = 'D', P = 'P' };

/* Short names for the tables below. */
static constexpr FoldShape K = FoldShape::K;
static constexpr FoldShape D = FoldShape::D;
static constexpr FoldShape P = FoldShape::P;

struct FoldRun {
    uint32_t first;
    uint32_t last;
    int32_t value;
    FoldShape shape;
};

/* Binary search in a table sorted by `first`; returns cp itself when no run
 * contains it. */
template <size_t N>
static inline uint32_t fold_in(const FoldRun (&table)[N], uint32_t cp) {
    size_t lo = 0, hi = N;
    while (lo < hi) {
        const size_t mid = (lo + hi) / 2;
        const FoldRun& r = table[mid];
        if (cp < r.first) { hi = mid; continue; }
        if (cp > r.last) { lo = mid + 1; continue; }
        switch (r.shape) {
            case FoldShape::K: return (uint32_t)r.value;
            case FoldShape::D: return (uint32_t)((int32_t)cp + r.value);
            case FoldShape::P: return ((cp - r.first) % 2 == 0) ? cp + 1 : cp;
        }
        return cp;
    }
    return cp;
}

