/* Lowercase of `cp` (one codepoint), or `cp` itself. */
static inline uint32_t bert_lower(uint32_t cp) { return fold_in(kBertLower, cp); }

/* Uppercase counterpart of a lowercase letter, or `cp` itself: the inverse of
 * kBertLower, with ASCII added. Only needed to put the case back on a base
 * letter when accents are stripped but case is kept (rare mode), so a linear
 * scan is fine. */
static inline uint32_t bert_upper(uint32_t cp) {
    if (cp >= 'a' && cp <= 'z') return cp - 0x20;
    if (cp < 0x80) return cp;
    for (const FoldRun& r : kBertLower) {
        switch (r.shape) {
            case FoldShape::K:
                if ((uint32_t)r.value == cp) return r.first;
                break;
            case FoldShape::D:
                if (cp >= (uint32_t)((int32_t)r.first + r.value) &&
                    cp <= (uint32_t)((int32_t)r.last + r.value))
                    return (uint32_t)((int32_t)cp - r.value);
                break;
            case FoldShape::P:
                if (cp > r.first && cp <= r.last + 1 && (cp - r.first - 1) % 2 == 0) return cp - 1;
                break;
        }
    }
    return cp;
}

/* Hangul syllables decompose algorithmically (Unicode ch. 3.12) into leading
 * consonant, vowel and optional trailing consonant. None of the jamo is Mn,
 * so after strip_accents a syllable is two or three codepoints. */
static inline bool append_hangul_nfd(std::string& out, uint32_t cp) {
    if (cp < 0xAC00 || cp > 0xD7A3) return false;
    const uint32_t s = cp - 0xAC00;
    append_utf8(out, 0x1100 + s / 588);
    append_utf8(out, 0x1161 + (s % 588) / 28);
    if (s % 28) append_utf8(out, 0x11A7 + s % 28);
    return true;
}

